    {
        int home = -1;
        bool htp = false, ber = false, produced = false;
        MuCase c;
        c.fixes = lvl;
        c.name = "htp + berekar";
        c.factions = {-1, W, SOL};
        c.act = 0;
        c.setup = [&](Game& g) {
            home = g.players[f].homeSystem;
            giveTech(g, f, "htp");
            muLeader(g, f, kAgent, kReady);
            freeTokens(g, f, 8);
            return true;
        };
        c.atActSet = [&](Game& g) {
            for (int x : controlledPlanets(g, f)) g.planets[size_t(x)].exhausted = false;
            g.players[f].exhaustedTechs.clear();
        };
        c.drive = [&](const Game& g, const Decision& d, Answer& a) {
            if (d.player != f) return false;
            if (d.tag == Tag::Activate) return pickOne(a, home);
            if (d.tag == Tag::ActivateConfirm) return pickOne(a, 1);
            if (d.tag == Tag::Movement) {
                a = Answer{};
                return true;
            }
            if (d.tag == Tag::Faction && d.ability == int(Ab::WinnuAgent)) {
                ber = true;
                return pickOne(a, 1);
            }
            if (d.tag == Tag::Faction && d.ability == int(Ab::HegemonicTrade)) {
                htp = true;
                for (const Option& op : d.options)
                    if (op.id >= 0) return pickOne(a, op.id);
            }
            if (d.kind == DecisionKind::Produce && !produced) {
                produced = true;
                a = Answer{};
                a.data.assign(size_t(kUnitTypes) + 1, 0);
                a.data[size_t(int(UnitType::Cruiser))] = 1;
                a.data[size_t(kUnitTypes)] = -1;
                return true;
            }
            (void)g;
            return false;
        };
        MuResult r = muRun(c);
        report("8 Hegemonic Trade Policy", r.acted && htp && lineWith(r, "(Hegemonic Trade Policy)"), std::string(htp ? "offered and used" : "NOT offered"));
        report("9 Berekar Berekon", r.acted && ber && lineWith(r, "costs 2 less (Berekar Berekon)"), std::string(ber ? "offered and used" : "NOT offered"));
    }
