    // command token, and the card goes back
    {
        bool acq = false;
        int stratAt = -1;
        MuCase c;
        c.fixes = lvl;
        c.modules = kModCodex;
        c.name = "acquiescence omega";
        c.factions = {-1, W, SOL};
        c.driveEarly = true;
        c.actPick = [](const Game& g, const Decision& d) {
            for (const Option& op : d.options)
                if (op.id >= 10 && op.id < 20 && op.enabled) return op.id;
            (void)g;
            return d.options[0].id;
        };
        c.setup = [&](Game& g) {
            if (g.speaker == f) return false;
            auto& h = g.players[f].notes;
            auto it = std::find(h.begin(), h.end(), makeNote(f, kNoteFaction));
            if (it == h.end()) return false;
            h.erase(it);
            g.players[o].notes.push_back(makeNote(f, kNoteFaction));
            g.players[o].strategy = 2;
            return true;
        };
        c.drive = [&](const Game& g, const Decision& d, Answer& a) {
            if (d.player == f && d.tag == Tag::StrategyPick) {
                for (const Option& op : d.options)
                    if (op.id == 6 && op.enabled) return pickOne(a, 6);
                return false;
            }
            if (d.player == o && d.tag == Tag::SecondaryUse && g.activePlayer == f) {
                stratAt = g.players[o].strategy;
                return pickOne(a, 1);
            }
            if (d.player == o && d.tag == Tag::Faction && d.ability == int(Ab::Acquiescence)) {
                acq = true;
                return pickOne(a, 1);
            }
            return false;
        };
        MuResult r = muRun(c);
        const bool back = holdsNote(r.end, f, f, kNoteFaction);
        report("14 Acquiescence (Omega)", r.acted && acq && back && r.end.players[o].strategy == stratAt,
               std::string(acq ? "played for the secondary" : "NOT played") + (back ? ", back with the Winnu" : ", NOT back") + ", the holder's strategy pool " +
                   std::to_string(stratAt) + " -> " + std::to_string(r.end.players[o].strategy));
    }
