                int Y = -1;  // (the flagship next to the combat, out of it)
                for (int16_t a : g.systems[size_t(T)].adj)
                    if (Y < 0 && a != Hs && !g.systems[size_t(a)].offBoard && !g.systems[size_t(a)].isHyperlane() && g.systems[size_t(a)].home < 0 &&
                        !isAnomaly(g, a) && a != g.mecatol())
                        Y = a;
                if (Y < 0) return false;
