        for (int x : controlledPlanets(r.end, o)) sol1 += r.end.planets[size_t(x)].units[o].count(UnitType::Infantry);
        const bool gone = P >= 0 && r.end.planets[size_t(P)].units[f].count(UnitType::Mech) == 0;
        report("14 Watcher", r.acted && asked && gone && lineWith(r, "Watcher cancels") && sol1 == sol0,
               std::string(asked ? "the Empyrean asked" : "NOT asked") + (gone ? ", the mech removed" : ", the mech STAYS") +
                   (sol1 == sol0 ? ", the card cancelled" : ", the card RESOLVED"));
