    // ---- 20. Void Tether: "place or move 1 of your Void Tether tokens" - with both out, the Empyrean choose which one moves
    // (here the newer one; the old rules moved the older one)
    {
        int H = -1, T = -1;
        std::pair<int16_t, int16_t> t0{-1, -1}, t1{-1, -1};
        bool asked = false;
        MuCase c;
        c.fixes = lvl;
        c.modules = kModThundersEdge;
        c.name = "void tether which";
        c.factions = {-1, E, SOL};
        c.act = 0;
        c.setup = [&](Game& g) {
            g.players[f].breakthrough = true;
            H = g.players[f].homeSystem;
            T = nextTo(g, H);
            if (T < 0) return false;
            std::vector<std::pair<int16_t, int16_t>> b;  // two board borders away from T
            for (size_t x = 0; x < g.systems.size() && b.size() < 2; ++x) {
                if (int(x) == T || int(x) == H || g.systems[x].offBoard || g.systems[x].isHyperlane()) continue;
                for (int16_t a : g.systems[x].adj)
                    if (b.size() < 2 && a != T && a != H && int(x) < a && !g.systems[size_t(a)].offBoard &&
                        hexDistance(g.systems[x].pos, g.systems[size_t(a)].pos) == 1 && (b.empty() || (b[0].first != int(x) && b[0].second != a))) {
                        b.push_back({int16_t(x), a});
                        break;
                    }
            }
            if (b.size() < 2) return false;
            t0 = b[0];
            t1 = b[1];
            g.tethers = b;
            clearShips(g, f, H);
            g.systems[size_t(H)].space[f].add(UnitType::Carrier, 1);
            freeTokens(g, f, 3);
            return true;
        };
        c.drive = moveDrive(f, [&] { return T; }, [&] { return std::vector<int>{H, -1, CV, 1}; },
                            [&](const Game&, const Decision& d, Answer& a) {
                                if (d.player != f || d.tag != Tag::Faction || d.ability != int(Ab::BtEmpyrean)) return false;
                                if (d.prompt.find("place a new tether or move one") != std::string::npos) {
                                    asked = true;
                                    return pickOne(a, 1001);  // the newer one
                                }
                                for (const Option& op : d.options)
                                    if (op.id >= 0) return pickOne(a, op.id);
                                return false;
                            });
        MuResult r = muRun(c);
        bool keptOld = false, keptNew = false;
        for (const auto& t : r.end.tethers) keptOld = keptOld || t == t0, keptNew = keptNew || t == t1;
        report("20 Void Tether (which token moves)", r.acted && asked && keptOld && !keptNew && r.end.tethers.size() == 2,
               std::string(asked ? "the Empyrean chose" : "NOT asked") + (keptOld && !keptNew ? ", the newer one moved" : keptNew && !keptOld ? ", the OLDER one moved" : ""));
    }
