    // ---- 10. Iconoclast (mech, without the Codex): +2 to its combat rolls against an opponent with a relic fragment - the
    // Naalu mech's dice: 4s and 5s hit, 1-3 miss
    {
        int H = -1, S = -1, P = -1;
        MuCase c;
        c.fixes = lvl;
        c.name = "iconoclast";
        c.factions = {HAC, N, SOL};
        c.act = 0;
        c.setup = [&](Game& g) {
            H = g.players[f].homeSystem;
            S = muPlainNext(g, H, 1);
            if (S < 0) return false;
            clearSystem(g, S);
            P = g.systems[size_t(S)].planets[0];
            g.planets[size_t(P)].owner = int8_t(o);
            g.planets[size_t(P)].units[o].add(UnitType::Infantry, 4);
            g.players[o].fragments.push_back(int16_t(findExploreCard("crf")));
            clearShips(g, f, H);
            g.systems[size_t(H)].space[f].add(UnitType::Carrier, 1);
            g.systems[size_t(H)].space[f].add(UnitType::Mech, 2);
            freeTokens(g, f, 3);
            return true;
        };
        c.drive = moveDrive(f, [&] { return S; }, [&] { return std::vector<int>{H, -1, CV, 1, H, -1, MECH, 2}; }, [&](const Game&, const Decision& d, Answer& a) {
            if (d.player == f && d.tag == Tag::LandForces) {
                a = Answer{};
                a.data = {P, MECH, 2};
                return true;
            }
            return false;
        });
        MuResult r = muRun(c);
        int seen45 = 0, wrong = 0;
        for (const std::string& l : r.log) {
            if (l.rfind("Naalu - Ground combat round", 0) != 0) continue;
            const size_t c0 = l.find(": ");
            std::string body = l.substr(c0 + 2, l.find(" = ") - c0 - 2);
            size_t i = 0;
            while (i < body.size()) {
                while (i < body.size() && !std::isdigit(static_cast<unsigned char>(body[i]))) ++i;
                if (i >= body.size()) break;
                int v = 0;
                while (i < body.size() && std::isdigit(static_cast<unsigned char>(body[i]))) v = v * 10 + (body[i++] - '0');
                const bool hit = i < body.size() && body[i] == '*';
                if (v >= 4 && v <= 5) {
                    ++seen45;
                    if (!hit) ++wrong;
                }
                if (v <= 3 && hit) ++wrong;
            }
        }
        report("10 Iconoclast (+2 against relic fragments)", r.acted && seen45 > 0 && wrong == 0,
               std::to_string(seen45) + " mech dice of 4-5, " + std::to_string(wrong) + " not as +2 would have them");
    }
