    // ---- 2 / 3. Fragile (-1 to the combat rolls) with J.N.S. Hylarim (each natural 9 or 10: 2 more hits): the flagship and a
    // dreadnought attack Sol's carriers - needs 7 7 (the flagship 6+1, twice) and 6 (the dreadnought 5+1); the hits counted
    // with the Hylarim's extra ones (seeds until a 9 or 10 comes up)
    {
        bool nineSeen = false, needsOk = false, hitsOk = false;
        std::string needs = "-";
        for (uint32_t sd = 0; sd < 8 && !nineSeen; ++sd) {
            int H = -1, T = -1;
            MuCase c;
            c.fixes = lvl;
            c.seed = 9090 + sd * 37;
            c.name = "fragile space";
            c.factions = {HAC, JN, SOL};
            c.act = 0;
            c.setup = [&](Game& g) {
                H = g.players[f].homeSystem;
                T = muPlainNext(g, H, 0);
                if (T < 0) return false;
                clearSystem(g, T);
                clearShips(g, f, H);
                g.systems[size_t(H)].space[f].add(UnitType::Flagship, 1);
                g.systems[size_t(H)].space[f].add(UnitType::Dreadnought, 1);
                g.systems[size_t(T)].space[o].add(UnitType::Carrier, 3);
                freeTokens(g, f, 4);
                return true;
            };
            c.drive = moveDrive(f, [&] { return T; }, [&] { return std::vector<int>{H, -1, FS, 1, H, -1, DN, 1}; }, [&](const Game&, const Decision& d, Answer& a) {
                if (d.tag == Tag::Retreat) return pickOne(a, 0);
                return false;
            });
            MuResult r = muRun(c);
            const MuRoll* m = rollOf(r, f, "Combat round 1");
            if (!m) continue;
            needs = show(m->need);
            needsOk = show(m->need) == "6 7 7";
            int want = 0;
            for (size_t i = 0; i < m->dice.size(); ++i) {
                if (m->dice[i] >= m->need[i]) ++want;
                if (m->need[i] == 7 && m->dice[i] >= 9) {
                    want += 2;
                    nineSeen = true;
                }
            }
            hitsOk = m->hits == want;
        }
        report("2 Fragile (space combat)", needsOk, "the flagship and a dreadnought need " + needs + " (6 7 7)");
        report("3 J.N.S. Hylarim", nineSeen && hitsOk, nineSeen ? (hitsOk ? "a 9 or 10 made 2 more hits" : "the extra hits WRONG") : "no 9 or 10 in 8 seeds");
    }
