    // ---- 13. Spatial Conduit Cylinder: "You may exhaust this card after you activate a system that contains 1 or more of your
    // units; that system is adjacent to all other systems that contain 1 or more of your units during this activation" - the
    // Jol-Nar activate a system with their infantry on a planet; a cruiser 3 systems away moves in
    {
        int H = -1, T = -1, F = -1;
        bool asked = false;
        MuCase c;
        c.fixes = lvl;
        c.name = "spatial conduit";
        c.factions = {HAC, JN, SOL};
        c.act = 0;
        c.setup = [&](Game& g) {
            H = g.players[f].homeSystem;
            T = muPlainNext(g, H, 1);
            if (T < 0) return false;
            F = -1;
            for (size_t s = 0; s < g.systems.size() && F < 0; ++s) {
                const SystemState& ss = g.systems[s];
                if (ss.offBoard || ss.isHyperlane() || ss.home >= 0 || isAnomaly(g, int(s)) || int(s) == g.mecatol()) continue;
                bool far = true;
                for (int x : systemsWithin(g, T, 2))
                    if (x == int(s)) far = false;
                if (!far || shipReach(g, f, int(s), T, UnitType::Cruiser, 1).ok) continue;  // (out of reach without the conduit)
                bool empty = true;
                for (int q = 0; q < kSides; ++q) empty = empty && ss.space[size_t(q)].empty();
                if (empty) F = int(s);
            }
            if (F < 0) return false;
            clearSystem(g, T);
            const int P = g.systems[size_t(T)].planets[0];
            g.planets[size_t(P)].owner = int8_t(f);
            g.planets[size_t(P)].units[f].add(UnitType::Infantry, 1);
            g.systems[size_t(F)].space[f].add(UnitType::Cruiser, 1);
            giveTech(g, f, "scc");
            freeTokens(g, f, 4);
            return true;
        };
        c.drive = moveDrive(f, [&] { return T; }, [&] { return std::vector<int>{F, -1, CA, 1}; }, [&](const Game&, const Decision& d, Answer& a) {
            if (d.player == f && d.tag == Tag::Faction && d.ability == int(Ab::SpatialConduit)) {
                asked = true;
                return pickOne(a, 1);
            }
            return false;
        });
        MuResult r = muRun(c);
        const bool there = T >= 0 && r.end.systems[size_t(T)].space[f].count(UnitType::Cruiser) == 1;
        report("13 Spatial Conduit Cylinder", r.acted && asked && there,
               std::string(asked ? "offered" : "NOT offered") + (there ? ", the far cruiser moved in" : ", the cruiser did NOT arrive"));
    }
