                const PlanetState& ps = g.planets[x];
                if (ps.system < 0 || ps.owner >= 0 || g.systems[size_t(ps.system)].home >= 0 || !planetHasSkip(g, int(x)) || !plainSys(g, ps.system, -1)) continue;
                P = int(x);
