    // a space combat at the Nekro home: Sol (the active player) move `sol` from S next door into it; the Nekro there have `nek` in
    // space and `inf` infantry / `mech` mechs on Mordai II; R: another system next door (empty)
    struct Home {
        int H = -1, S = -1, R = -1, M = -1;
    };
    auto homeFight = [&](const char* name, std::vector<std::pair<UnitType, int>> nek, int inf, int mech, std::vector<std::pair<UnitType, int>> sol,
                         std::function<void(Game&)> more, std::function<bool(const Game&, const Decision&, Answer&)> drive2, Home& hm) {
        MuCase c = kase(name);
        c.actor = o;
        c.setup = [=, &hm](Game& g) {
            hm.H = g.players[f].homeSystem;
            hm.S = hm.R = -1;
            for (int16_t t : g.systems[size_t(hm.H)].adj)
                if (plainSys(g, t, -1)) {
                    if (hm.S < 0) hm.S = t;
                    else if (hm.R < 0) hm.R = t;
                }
            if (hm.S < 0 || hm.R < 0) return false;
            hm.M = g.systems[size_t(hm.H)].planets[0];
            clearShips(g, f, hm.H);
            for (auto& s : nek) g.systems[size_t(hm.H)].space[f].add(s.first, s.second);
            Force& on = g.planets[size_t(hm.M)].units[f];
            on.n[INF] = uint8_t(inf);
            on.n[int(UnitType::Mech)] = uint8_t(mech);
            for (auto& s : sol) g.systems[size_t(hm.S)].space[o].add(s.first, s.second);
            onlyTechs(g, o, {});
            freeTokens(g, o, 6);
            if (more) more(g);
            return true;
        };
        c.drive = moveDrive(o, [&hm] { return hm.H; },
                            [&hm, sol] {
                                std::vector<int> v;
                                for (auto& s : sol) v.insert(v.end(), {hm.S, -1, int(s.first), s.second});
                                return v;
                            },
                            [=](const Game& g, const Decision& d, Answer& a) {
                                if (drive2 && drive2(g, d, a)) return true;
                                if (d.player == f && fab(d, Ab::TechSingularity)) return pickOne(a, -1);
                                if (d.tag == Tag::SpaceCannonFire || d.tag == Tag::Retreat || d.tag == Tag::RetreatCargo) return pickOne(a, 0);
                                return false;
                            });
        return c;
    };
    auto alastorAll = [&](const Decision& d, Answer& a) {  // every ground force joins
        int most = 0;
        for (const Option& op : d.options) most = std::max(most, op.id);
        return pickOne(a, most);
    };
    // ---- N19. The Alastor with the planet's ground forces (owner 2026-11-14: "if I have 6 infantry on planet A, and 3 infantry in
