        c.atActSet = [&](Game& g) { give(g, f, "nav_suite"); };
        c.drive = moveDrive(f, [&] { return A; }, [&] { return std::vector<int>{X, -1, CV, 1}; }, play(f, "nav_suite", off, nullptr));
