    // ================================================================ strategy, status and agenda phases (the card goes in when the
    // Hacan take their first action; the game plays on to the end of round 1 / 2; the Hacan pass when they can)
    auto later = [&](const char* name, int rounds, bool agenda, const char* topAgenda) {
        MuCase c = kase(name);
        c.actPick = stratPick;
        c.untilRound = rounds;
        c.setup = [=](Game& g) {
            if (agenda) g.custodiansRemoved = true;
            if (topAgenda) g.agendaDeck.push_back(int16_t(findAgenda(topAgenda)));
            for (int k = 0; k < 30; ++k) g.actionDeck.push_back(int16_t(findActionCard("f_deployment")));
            return true;
        };
        return c;
    };
    // ---- C1. Summit: "At the start of the strategy phase: Gain 2 command tokens"
    {
        bool off = false, two = false;
        MuCase c = later("summit", 2, false, nullptr);
        c.atActSet = [&](Game& g) { give(g, f, "summit"); };
        c.drive = play(f, "summit", off, [&](const Game&, const Decision& d, Answer& a) {
            if (d.player == f && d.kind == DecisionKind::Tokens && d.newTokens == 2 && d.context.find("Summit") != std::string::npos) two = true;
            return passLater(d, a, f);
        });
        MuResult r = muRun(c);
        report("C1 Summit", r.acted && off && two, std::string(off ? "played at the start of the strategy phase" : "NOT offered") + (two ? ", 2 tokens" : ", NO tokens"));
    }
