    // ---- C8. The riders: "After an agenda is revealed: You cannot vote on this agenda. Predict aloud an outcome of this agenda.
    // If your prediction is correct, ..." - everyone votes for the predicted outcome
    {
        struct Rider {
            const char* key;
            const char* check;  // a log line of the reward
        };
        const Rider riders[] = {{"imp_rider", "gains 1 victory point (Imperial Rider)"},
                                {"trade_rider", "Hacan's Trade Rider was right!"},
                                {"lead_rider", "Hacan's Leadership Rider was right!"},
                                {"tech_rider", "Hacan researches"},
                                {"politic_rider", "Hacan becomes the speaker."},
                                {"const_rider", "Hacan's Construction Rider was right!"},
                                {"war_rider", "(Warfare Rider)"},
                                {"diplo_rider", "Hacan's Diplomacy Rider was right!"},
                                {"sanction", "loses a fleet token (Sanction)"}};
        for (const Rider& rd : riders) {
            bool off = false, voted = false;
            int pred = -999, tok = -1, tg0 = -1, tg1 = -1;
            MuCase c = later(rd.key, 1, true, "incentive");
            c.atActSet = [&](Game& g) { give(g, f, rd.key); };
            c.drive = play(f, rd.key, off, [&](const Game& g, const Decision& d, Answer& a) {
                if (d.player == f && d.tag == Tag::VoteOutcome && g.agendaNumber == 0) voted = true;
                if (g.agendaNumber == 1 && tg1 < 0) tg1 = g.players[f].tradeGoods;
                if (d.player == f && d.tag == Tag::Predict && pred == -999) {
                    pred = d.options[0].id;
                    tg0 = g.players[f].tradeGoods;
                    return pickOne(a, pred);
                }
                if (d.tag == Tag::VoteOutcome && pred != -999 && has(d, pred)) return pickOne(a, pred);
                if (d.player == f && d.kind == DecisionKind::Tokens && d.context.find("Leadership Rider") != std::string::npos) tok = d.newTokens;
                return passLater(d, a, f);
            });
            MuResult r = muRun(c);
            bool ok = r.acted && off && lineWith(r, rd.check) && !voted;
            std::string what = std::string(off ? "played" : "NOT offered") + (lineWith(r, rd.check) ? ", rewarded" : ", NOT rewarded") + (voted ? ", the Hacan VOTED" : "");
            if (!std::strcmp(rd.key, "trade_rider")) {
                ok = ok && tg1 == tg0 + 5;
                what += ", " + std::to_string(tg1 - tg0) + " trade goods (5)";
            }
            if (!std::strcmp(rd.key, "lead_rider")) {
                ok = ok && tok == 3;
                what += ", " + std::to_string(tok) + " tokens (3)";
            }
            if (!std::strcmp(rd.key, "politic_rider")) ok = ok && r.end.speaker == f;
            report((std::string("C8 ") + kActionCards[size_t(AC(rd.key))].name).c_str(), ok, what);
        }
    }
