            g.planets[size_t(P0)].owner = g.planets[size_t(P1)].owner = int8_t(o);
            g.planets[size_t(P0)].units[o].add(UnitType::Infantry, 1);
            g.planets[size_t(P1)].units[o].add(UnitType::Infantry, 3);
