    // ---- invasion helper: the Hacan (f) move `ships` from home into T (next to their home) and land `land` infantry on its planet
    // P, which Sol holds with `solInf` infantry (+ a PDS when solPds); `drive2` answers the rest
    struct Inv {
        int T = -1, P = -1;
    };
    auto invadeCase = [&](const char* name, int modules, std::vector<std::pair<UnitType, int>> ships, int land, int solInf, bool solPds,
                          std::function<void(Game&)> more, std::function<bool(const Game&, const Decision&, Answer&)> drive2, Inv& iv) {
        MuCase c = kase(name);
        c.modules = modules;
        c.setup = [=, &iv](Game& g) {
            const int H = g.players[f].homeSystem;
            iv.T = -1;
            for (int16_t t : g.systems[size_t(H)].adj)
                if (plainSys(g, t, 1)) {
                    iv.T = t;
                    break;
                }
            if (iv.T < 0) return false;
            iv.P = g.systems[size_t(iv.T)].planets[0];
            g.planets[size_t(iv.P)].owner = int8_t(o);
            if (solInf) g.planets[size_t(iv.P)].units[o].add(UnitType::Infantry, solInf);
            if (solPds) g.planets[size_t(iv.P)].units[o].add(UnitType::PDS, 1);
            onlyTechs(g, o, {});
            onlyTechs(g, f, {});
            clearShips(g, f, H);
            for (auto& s : ships) g.systems[size_t(H)].space[f].add(s.first, s.second);
            if (land) g.systems[size_t(H)].space[f].add(UnitType::Infantry, land);
            freeTokens(g, f, 6);
            if (more) more(g);
            return true;
        };
        c.drive = moveDrive(f, [&iv] { return iv.T; }, [&iv] { return std::vector<int>{-1}; }, [=, &iv](const Game& g, const Decision& d, Answer& a) {
            if (drive2 && drive2(g, d, a)) return true;
            if (d.player == f && d.tag == Tag::Movement) {
                const int H = g.players[f].homeSystem;
                a = Answer{};
                for (auto& s : ships) {
                    a.data.push_back(H);
                    a.data.push_back(-1);
                    a.data.push_back(int(s.first));
                    a.data.push_back(s.second);
                }
                if (land) {
                    a.data.push_back(H);
                    a.data.push_back(-1);
                    a.data.push_back(INF);
                    a.data.push_back(land);
                }
                return true;
            }
            if (d.player == f && d.tag == Tag::LandForces) {
                a = Answer{};
                if (land) a.data = {iv.P, INF, land};
                return true;
            }
            if (d.tag == Tag::SpaceCannonFire || d.tag == Tag::Retreat) return pickOne(a, 0);
            return false;
        });
        return c;
    };
