    // ---- production at home: the Hacan activate their home and build `build`; techs `ts`; returns the case (tgSpent measured)
    auto homeBuild = [&](const char* name, std::initializer_list<const char*> ts, std::vector<std::pair<UnitType, int>> build, int& tg0, int& tg1,
                         std::function<bool(const Game&, const Decision&, Answer&)> drive2) {
        MuCase c = kase(name);
        std::vector<const char*> tl(ts);
        c.setup = [=](Game& g) {
            g.players[f].techs.clear();
            for (const char* k : tl) giveTech(g, f, k);
            freeTokens(g, f, 6);
            return true;
        };
        c.atActSet = [&tg0, f](Game& g) {
            for (PlanetState& ps : g.planets)
                if (ps.owner == f) ps.exhausted = true;
            g.players[f].tradeGoods = 10;
            tg0 = 10;
        };
        c.drive = moveDrive(f, [] { return -2; }, [] { return std::vector<int>{}; }, [=, &tg1](const Game& g, const Decision& d, Answer& a) {
            if (d.player == f && d.tag == Tag::Activate) return pickOne(a, g.players[f].homeSystem);
            if (drive2 && drive2(g, d, a)) return true;
            if (d.player == f && d.kind == DecisionKind::Produce && d.tag == Tag::Production) {
                std::vector<int> v(size_t(kUnitTypes) + 1, 0);
                for (auto& b : build) v[int(b.first)] += b.second;
                v[kUnitTypes] = -1;
                for (int16_t x : g.systems[size_t(g.players[f].homeSystem)].planets)
                    if (g.planets[size_t(x)].units[f].count(UnitType::SpaceDock)) v[kUnitTypes] = x;
                a = Answer{};
                a.data = v;
                return true;
            }
            if (d.player == f && d.tag == Tag::ActionChoice) tg1 = g.players[f].tradeGoods;
            return false;
        });
        return c;
    };
