    // prerequisite" - Dreadnought II (blue, blue, yellow) with Gravity Drive (blue) and Sarween Tools (yellow) only
    {
        MuCase c = kase("aida research");
        c.driveEarly = true;
        c.actPick = [](const Game&, const Decision& d) {
            for (const Option& op : d.options)
                if (op.id == 16) return 16;
            return 0;
        };
        c.setup = [&](Game& g) {
            onlyTechs(g, f, {"aida", "gd", "st"});
            for (PlanetState& ps : g.planets)
                if (ps.owner == f) ps.exhausted = true;
            return true;
        };
        c.drive = [&](const Game& g, const Decision& d, Answer& a) {
            if (d.tag == Tag::StrategyPick) {
                a = Answer{};
                for (const Option& op : d.options)
                    if (op.id == 6 && d.player == f) {
                        a.picks = {6};
                        return true;
                    }
                for (const Option& op : d.options)
                    if (op.id != 6) {
                        a.picks = {op.id};
                        return true;
                    }
                return false;
            }
            if (d.player == f && d.tag == Tag::Research) return pickOne(a, has(d, findTech("dn2")) ? findTech("dn2") : d.options[0].id);
            if (d.player == f && d.prompt.find("AI Development") != std::string::npos) return pickOne(a, 1);
            if (d.player == f && d.tag == Tag::ExtraResearch) return pickOne(a, 0);
            (void)g;
            return false;
        };
        MuResult r;
        for (uint32_t sd = 0; sd < 40; ++sd) {
            c.seed = 9090 + sd * 71;
            r = muRun(c);
            if (r.acted && r.atAct.cardOwner[6] == f) break;
        }
        const bool got = r.end.players[f].hasTech(findTech("dn2")), used = lineWith(r, "uses AI Development Algorithm");
        report("26 AI Development Algorithm (research)", r.acted && r.atAct.cardOwner[6] == f && got && used && exhausted(r.end, f, "aida"),
               std::string(got ? "Dreadnought II researched" : "NO Dreadnought II") + (used ? ", the algorithm used" : ", NOT used"));
    }
    // ---- 27. Self-Assembly Routines: "After 1 or more of your units use PRODUCTION, you may exhaust this card to place 1 mech from your
